-- 3. detectors that keep the local-only halves and the wiring visible
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('e2-credential-missing-claim', 'an open issue or card claims a credential, token, secret or api key is missing and nobody has tested the claim', 'RM-GATE-E2 (fleet-lessons E2): a secret''s presence was once judged from the process environment, not its file store (~/.qnfo/*, ~/.env, .deepchat/secrets), giving a false missing-credential blocker that was handed to the owner', 'red-team the claim before it stands: read the file stores and the Worker secret list, falsify with the credential, and record the attempt in blocker_redteam (verdict false-belief-removed, workaround-built or confirmed-with-evidence)', 'the fm-e2-credential-missing-claim contract counts v_blocker_claims rows whose text names a credential, token, secret or api key, expected 0', 'fm-e2-credential-missing-claim', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'an open agent_issues row or human_actions card older than the grace period whose title names a missing credential and that has no blocker_redteam row in 24 hours', 'blocker_survival_rate_7d and unverified_blocker_claims rise; the owner is asked for something the files already hold', 'any loop: a false blocker is handed to the owner');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-e2-credential-missing-claim', NULL, 'C4-GATES-ROADMAP-CLOSEOUT-1: an open issue or card claims a credential, token, secret or api key is missing and nobody has tested the claim', 'Read the claim in v_blocker_claims, attempt the step with what exists (file stores, secret list, the sibling route), write the attempt to blocker_redteam; an owner card that survives carries an IDENTITY-BOUND: line', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM v_blocker_claims WHERE lower(text) LIKE ''%credential%'' OR lower(text) LIKE ''%token%'' OR lower(text) LIKE ''%secret%'' OR lower(text) LIKE ''%api key%'') AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('h5-owner-restart-handoff', 'a card tells the owner to restart, relaunch or reload an app, a step the agent can execute itself', 'RM-GATE-H5 (fleet-lessons H5): editing a config file was reported as a runtime change while the running app still held the old state, and the restart was handed to the user', 'reconcile the runtime state in the session and execute the restart or reload through the tool surface; only an action that is irreversible and identity-bound stays with the owner', 'the fm-h5-owner-restart-handoff contract counts open human_actions whose title or action says restart, relaunch or reload the app, expected 0', 'fm-h5-owner-restart-handoff', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'an open human_actions card whose title or action asks the owner to restart, relaunch or reload an application', 'the owner queue holds a chore a tool can do', 'the owner queue: owner load grows with steps the fleet could take');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-h5-owner-restart-handoff', NULL, 'C4-GATES-ROADMAP-CLOSEOUT-1: a card tells the owner to restart, relaunch or reload an app, a step the agent can execute itself', 'Execute the restart or reload through the tool surface, verify the running state in the same session, then resolve the card with that evidence; reroute it to the fleet when it is not identity-bound', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM human_actions WHERE status = ''open'' AND (lower(title || '' '' || COALESCE(action, '''')) LIKE ''%restart%'' OR lower(title || '' '' || COALESCE(action, '''')) LIKE ''%relaunch%'' OR lower(title || '' '' || COALESCE(action, '''')) LIKE ''%reload the app%'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('fleet-lessons-gates-wired', 'the fleet-lessons repository gates are not wired into the PR-time fast guards, so they gate nothing', 'ledger entry G4: a guard that is not wired into the gate that runs is not a gate; scripts/fleet_lessons_gates.py (C1, C3, D4, H1, H2, H3) runs only when scripts/pr_fast_guards.py lists it', 'register fleet-lessons-gates in the GUARDS list of scripts/pr_fast_guards.py (through scripts/regression_gate.py), applies when scripts/, docs/ops-governance/ or a worker entry the gates read changes', 'the fm-fleet-lessons-gates-wired contract reads scripts/pr_fast_guards.py on main for the guard name, expected present', 'fm-fleet-lessons-gates-wired', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'scripts/pr_fast_guards.py on main no longer contains the text fleet-lessons-gates', 'a client-state, command-form, purge or link-probe regression reaches main without a PR check noticing', 'docs/ops-governance/scripts and the scripts the owner machine runs');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-fleet-lessons-gates-wired', NULL, 'C4-GATES-ROADMAP-CLOSEOUT-1: the fleet-lessons repository gates are not wired into the PR-time fast guards, so they gate nothing', 'Restore the GUARDS entry (name fleet-lessons-gates, command python3 scripts/fleet_lessons_gates.py) in scripts/pr_fast_guards.py by pull request', '{"paths": ["scripts/pr_fast_guards.py"], "contains": "fleet-lessons-gates"}', 'code-read', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('objective-revision-unanswered', 'an objective revision stays proposed for more than 14 days with no recorded decision', 'RM-S5-RATIFICATION-SURFACE-1: the dashboard records a ratify or reject (human_responses, objective_revision_applies) but nothing expired a proposal nobody answered', 'decide it: a delegable revision takes the recommended option under DEFAULT-APPROVE-1 through POST /api/owner/objective with the loop token, logged in decision_log with its revert path; a weight revision needs the owner''s emailed-code session (OBJECTIVE-WEIGHT-OWNER-ONLY-1), so it gets a human_actions card whose why carries an IDENTITY-BOUND: line and a closing probe, and the proposal is set superseded (expired, re-proposed by the review loop if it still holds)', 'the fm-objective-revision-unanswered contract counts goals of type objective-revision with status proposed and a created date older than 14 days, expected 0', 'fm-objective-revision-unanswered', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'a goals row with goal_type objective-revision and status proposed whose created_at is more than 14 days old', 'the owner queue shows a ratification card that never resolves; the objective function never changes or changes late', 'the terminal objective function (SAI weights and constraints)');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-objective-revision-unanswered', NULL, 'C4-GATES-ROADMAP-CLOSEOUT-1: an objective revision stays proposed for more than 14 days with no recorded decision', 'Decide the stale proposal as the failure mode describes and record the decision in decision_log with its revert path', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM goals WHERE goal_type = ''objective-revision'' AND status = ''proposed'' AND substr(replace(created_at, ''T'', '' ''), 1, 10) < date(''now'', ''-14 days'')) AS TEXT) AS observed', 'd1-query', 3, 'program-manager:QNFO.OPS', 1, 'active', 'failure-mode', datetime('now'));

