INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'custom-prompts-template-parity', status, 'completed', 'closeout-completed', 'COMPLETE (C4-GATES 2026-11-05): QNFO/qnfo-skills prompt-stores/customPrompts.json read through the GitHub API: 11 entries, 0 missing content, 0 missing template. The R2 mirror writer qnfo-skill-sync is retired (Cloudflare 1042) and prompt-store-verify is a local guard by design (agent_issues 1686); its repo-side parity now runs in CI (scripts/fleet_lessons_gates.py gate C1).' FROM goals WHERE goal_key = 'custom-prompts-template-parity' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'custom-prompts-template-parity' AND action = 'closeout-completed');
