INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'wrangler-deploy-fleet-control', status, 'superseded', 'closeout-retired', 'RETIRE (C4-GATES 2026-11-05): the structural half is met (qnfo-fleet-control/worker.js exports FleetAdvisor; wrangler.toml declares the durable_objects binding and [exports.FleetAdvisor] storage sqlite). The literal half (wrangler deploy without the API path) is not how the fleet deploys: canonical-deploy.yml calls qnfo-ops /ops/deploy, which installs declared bindings, with the canary and revert of CONTROL-PLANE-SELF-MERGE-1. Surviving: that canonical path and the deploy-gate dry-run.' FROM goals WHERE goal_key = 'wrangler-deploy-fleet-control' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'wrangler-deploy-fleet-control' AND action = 'closeout-retired');
