INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'fleet-loop-actuation-gap', status, 'adopted', 'closeout-review', 'KEEP (C4-GATES 2026-11-05): DoD not met. 5 DEPLOY-UNCOORDINATED-DEPLOY issues were created in the last 24h (1001861 qnfo-fleet-lee and 1001598 qnfo-fleet-control still open, 1001737 q08-mind, 1001664, 1001662); fleet_loop_meta.last_execute_summary reads scanned 3, executed 0. The AGENTIC-CANARY-1 and UPSTREAM_MODEL pin clauses are obsolete (BUDGET-SOFT-ROUTE-1; ops is measured by goal ops-model-toolcall-crisis). Closing probe: contract closeout-goal-fleet-loop-actuation-gap. Doer: qnfo-deploy-guard lane.' FROM goals WHERE goal_key = 'fleet-loop-actuation-gap' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'fleet-loop-actuation-gap' AND action = 'closeout-review');
INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'repo-mirror-drift-closeout', status, 'adopted', 'closeout-review', 'KEEP (C4-GATES 2026-11-05): DoD not met. scripts/mirror-guard.py on main: lagging 0, content_drift 0, missing_mirror 0, but the fleet graph (qnfo-graph.fg_finding kind untracked-worker) lists voice-stt and qnfo-fleet-lee as live workers with no code directory. Closing probe: contract closeout-goal-repo-mirror-drift-closeout (that count 0). Doer: portfolio manager QNFO.INFRA (import the live bundle with its mirror, or retire the worker).' FROM goals WHERE goal_key = 'repo-mirror-drift-closeout' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'repo-mirror-drift-closeout' AND action = 'closeout-review');
