INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'g1ungpzy41', status, 'adopted', 'closeout-review', 'KEEP (C4-GATES 2026-11-05): DoD (false positives under 20% for 2 consecutive months) cannot be met yet and the symptom is live: metric issue_relapse_families_7d reads 8 (trigger hit), fm-metric-close-flap, fm-reopen-hits-open-twin and fm-superseded-closure-reopened read fail. Adopted 2026-09-18, so the earliest pass is 2026-11-18. Closing measure: issue_relapse_families_7d at 0 on the metric tick. Doer: the metric-breach loop that owns METRIC-TRIGGER issue_relapse_families_7d.' FROM goals WHERE goal_key = 'g1ungpzy41' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'g1ungpzy41' AND action = 'closeout-review');
